package edu.bca.futsal.dao;
import java.sql.ResultSet; import java.sql.SQLException; import java.util.*;
import edu.bca.futsal.model.Account; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.core.RowMapper; import org.springframework.stereotype.Repository;
@Repository public class FutsalDao {
 private final JdbcTemplate db; public FutsalDao(JdbcTemplate db){this.db=db;}
 private static final RowMapper<Map<String,Object>> MAP=(r,n)->{Map<String,Object> m=new LinkedHashMap<>(); for(int i=1;i<=r.getMetaData().getColumnCount();i++)m.put(r.getMetaData().getColumnLabel(i),r.getObject(i)); return m;};
 public Account login(String email,String password){var rows=db.query("SELECT id,name,role FROM users WHERE email=? AND password=?",(r,n)->new Account(r.getInt("id"),r.getString("name"),r.getString("role")),email,password);return rows.isEmpty()?null:rows.get(0);}
 public List<Map<String,Object>> grounds(){return db.query("SELECT * FROM grounds ORDER BY name",MAP);}
 public List<String> bookedSlots(int ground,String date){return db.query("SELECT slot FROM bookings WHERE ground_id=? AND match_date=?",(r,n)->r.getString(1),ground,date);}
 public List<Map<String,Object>> bookings(){return db.query("SELECT b.*,g.name ground_name,u.name organizer_name FROM bookings b JOIN grounds g ON g.id=b.ground_id JOIN users u ON u.id=b.organizer_id ORDER BY b.match_date,b.slot",MAP);}
 public List<Map<String,Object>> bookingsFor(int organizer){return db.query("SELECT b.*,g.name ground_name FROM bookings b JOIN grounds g ON g.id=b.ground_id LEFT JOIN matches m ON m.booking_id=b.id WHERE b.organizer_id=? AND m.id IS NULL ORDER BY b.match_date,b.slot",MAP,organizer);}
 public List<Map<String,Object>> openMatches(int player){return db.query("SELECT m.*,u.name organizer_name,g.name ground_name,b.match_date,b.slot,(SELECT COUNT(*) FROM join_requests x WHERE x.match_id=m.id AND x.status='APPROVED') approved_count,COALESCE(j.status,'NONE') request_status FROM matches m JOIN users u ON u.id=m.organizer_id JOIN bookings b ON b.id=m.booking_id JOIN grounds g ON g.id=b.ground_id LEFT JOIN join_requests j ON j.match_id=m.id AND j.player_id=? WHERE m.status='OPEN' ORDER BY b.match_date,b.slot",MAP,player);}
 public Map<String,Object> matchDetails(int match,int player){var rows=db.query("SELECT m.*,u.name organizer_name,g.name ground_name,g.area,b.match_date,b.slot,(SELECT COUNT(*) FROM join_requests x WHERE x.match_id=m.id AND x.status='APPROVED') approved_count,COALESCE(j.status,'NONE') request_status FROM matches m JOIN users u ON u.id=m.organizer_id JOIN bookings b ON b.id=m.booking_id JOIN grounds g ON g.id=b.ground_id LEFT JOIN join_requests j ON j.match_id=m.id AND j.player_id=? WHERE m.id=?",MAP,player,match);return rows.isEmpty()?null:rows.get(0);}
 public List<Map<String,Object>> myMatches(int organizer){return db.query("SELECT m.*,g.name ground_name,b.match_date,b.slot,(SELECT COUNT(*) FROM join_requests j WHERE j.match_id=m.id AND j.status='APPROVED') approved_count FROM matches m JOIN bookings b ON b.id=m.booking_id JOIN grounds g ON g.id=b.ground_id WHERE m.organizer_id=? ORDER BY b.match_date DESC",MAP,organizer);}
 public List<Map<String,Object>> requests(int organizer){return db.query("SELECT j.id request_id,j.status,j.requested_at,u.name player_name,m.id match_id,m.title match_title,g.name ground_name,b.match_date,b.slot FROM join_requests j JOIN users u ON u.id=j.player_id JOIN matches m ON m.id=j.match_id JOIN bookings b ON b.id=m.booking_id JOIN grounds g ON g.id=b.ground_id WHERE m.organizer_id=? ORDER BY (j.status='PENDING') DESC,j.requested_at DESC",MAP,organizer);}
 public List<Map<String,Object>> myRequests(int player){return db.query("SELECT j.*,m.id match_id,m.title match_title,g.name ground_name,b.match_date,b.slot FROM join_requests j JOIN matches m ON m.id=j.match_id JOIN bookings b ON b.id=m.booking_id JOIN grounds g ON g.id=b.ground_id WHERE j.player_id=? ORDER BY j.requested_at DESC",MAP,player);}
 public int createBooking(int ground,int organizer,String date,String slot){return db.update("INSERT INTO bookings(ground_id,organizer_id,match_date,slot) VALUES(?,?,?,?)",ground,organizer,date,slot);}
 public int createMatch(int booking,int organizer,int needed,String title,String notes){return db.update("INSERT INTO matches(booking_id,organizer_id,title,additional_players_needed,notes) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM bookings WHERE id=? AND organizer_id=?)",booking,organizer,title,needed,notes,booking,organizer);}
 public int requestJoin(int match,int player){return db.update("INSERT INTO join_requests(match_id,player_id,status) SELECT id,?,'PENDING' FROM matches WHERE id=? AND status='OPEN' AND organizer_id<>?",player,match,player);}
 public Map<String,Object> lockMatch(int id){return db.queryForMap("SELECT m.*, (SELECT COUNT(*) FROM join_requests j WHERE j.match_id=m.id AND j.status='APPROVED') approved_count FROM matches m WHERE m.id=? FOR UPDATE",id);}
 public Map<String,Object> request(int id){return db.queryForMap("SELECT * FROM join_requests WHERE id=? FOR UPDATE",id);}
 public int setRequest(int request,String status){return db.update("UPDATE join_requests SET status=? WHERE id=?",status,request);}
 public int setMatchStatus(int id,String status){return db.update("UPDATE matches SET status=? WHERE id=?",status,id);}
 public int cancelApproved(int request,int player){return db.update("UPDATE join_requests SET status='CANCELLED' WHERE id=? AND player_id=? AND status='APPROVED'",request,player);}
 public boolean ownsMatch(int match,int organizer){return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM matches WHERE id=? AND organizer_id=?)",Boolean.class,match,organizer));}
}
